options.customCss:
div.html pre { max-height: 24em; overflow: auto; white-space: pre-wrap; word-break: break-word; overflow-wrap: anywhere; margin: 8px 0 16px; padding: 8px 10px; border: 1px solid #dbdfe7; border-radius: 4px; background: #f8f8fa; font-size: 12px; line-height: 1.4; user-select: all; -webkit-user-select: all; }
form textarea { min-height: 10em; }
div.html strong { color: #b00020; font-weight: 600; }

div.html em { font-style: normal; color: #7e8186; font-size: 12px; }
div.html ol { margin-top: 8px; }
div.html li { margin-bottom: 4px; }
div.html h4 { margin-top: 24px; font-weight: 600; }
div.html li:has(> i) { color: #7e8186; }
div.html li > i { font-style: normal; color: #7e8186; }
div.html strong { color: #b00020; font-weight: 600; }

